     6: /**
     7:  * SQLite database singleton.
     8:  *
     9:  * Opens a single file-backed connection shared across the app, ensures the
    10:  * parent directory exists, and initializes the schema. Never open a
    11:  * connection per request.
    12:  */
    13: 
    14: let db: Database.Database | null = null;
    15: 
    16: /**
    17:  * Get (creating on first use) the shared SQLite connection.
    18:  *
    19:  * Returns:
    20:  *   The shared better-sqlite3 database instance.
    21:  */
    22: export function getDb(): Database.Database {
    23:   if (db) {
    24:     return db;
    25:   }
    26:   const dir = path.dirname(config.databasePath);
    27:   if (!fs.existsSync(dir)) {
    28:     fs.mkdirSync(dir, { recursive: true });
    29:   }
    30:   db = new Database(config.databasePath);
    31:   db.pragma("journal_mode = WAL");
    32:   db.pragma("foreign_keys = ON");
    33:   initSchema(db);
    34:   return db;
    35: }
    36: 
    37: /**
    38:  * Initialize the database schema idempotently.
    39:  *
    40:  * Args:
    41:  *   database: The database instance to initialize.
    42:  */
    43: function initSchema(database: Database.Database): void {
    44:   database.exec(`
    45:     CREATE TABLE IF NOT EXISTS movies (
    46:       id INTEGER PRIMARY KEY AUTOINCREMENT,
    47:       title TEXT NOT NULL,
    48:       poster TEXT NOT NULL DEFAULT '',
    49:       genre TEXT NOT NULL DEFAULT '',
    50:       rating TEXT NOT NULL DEFAULT ''
    51:     );
    52:     CREATE TABLE IF NOT EXISTS theatres (
    53:       id INTEGER PRIMARY KEY AUTOINCREMENT,
    54:       name TEXT NOT NULL,
    55:       location TEXT NOT NULL DEFAULT ''
    56:     );
    57:     CREATE TABLE IF NOT EXISTS movie_theatres (
    58:       movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    59:       theatre_id INTEGER NOT NULL REFERENCES theatres(id) ON DELETE CASCADE,
    60:       PRIMARY KEY (movie_id, theatre_id)
    61:     );
    62:     CREATE TABLE IF NOT EXISTS bookings (
    63:       id INTEGER PRIMARY KEY AUTOINCREMENT,
