{"success":true,"tool_name":"read_file","data":{"content":"     1: import { getDb } from "./database";
     2: 
     3: /**
     4:  * Seed data for the replica catalog.
     5:  *
     6:  * The acceptance dataset from the PRD: three movies and three theatres, with
     7:  * every theatre showing every movie.
     8:  */
     9: const MOVIES = [
    10:   { title: "Paradise", poster: "/posters/paradise.svg", genre: "Drama", rating: "U/A" },
    11:   { title: "Bloody Romeo", poster: "/posters/bloody-romeo.svg", genre: "Action", rating: "A" },
    12:   { title: "OG2", poster: "/posters/og2.svg", genre: "Thriller", rating: "U/A" },
    13: ];
    14: 
    15: const THEATRES = [
    16:   { name: "Sandhya 70mm", location: "Hyderabad" },
    17:   { name: "Sudharsham 70mm", location: "Hyderabad" },
    18:   { name: "Allu Cinemas", location: "Hyderabad" },
    19: ];
    20: 
    21: /**
    22:  * Seed the database idempotently.
    23:  *
    24:  * Each insert is conditional on absence (checked by unique title/name), so
    25:  * running seed on every startup never duplicates rows. Also maps every movie
    26:  * to every theatre.
    27:  */
    28: export function seedDatabase(): void {
    29:   const db = getDb();
    30: 
    31:   const insertMovie = db.prepare(
    32:     "INSERT INTO movies (title, poster, genre, rating) SELECT ?, ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM movies WHERE title = ?)"
    33:   );
    34:   const insertTheatre = db.prepare(
    35:     "INSERT INTO theatres (name, location) SELECT ?, ? WHERE NOT EXISTS (SELECT 1 FROM theatres WHERE name = ?)"
    36:   );
    37:   const insertMapping = db.prepare(
    38:     "INSERT OR IGNORE INTO movie_theatres (movie_id, theatre_id) VALUES (?, ?)"
    39:   );
    40: 
    41:   const seedAll = db.transaction(() => {
    42:     for (const movie of MOVIES) {
    43:       insertMovie.run(movie.title, movie.poster, movie.genre, movie.rating, movie.title);
    44:     }
    45:     for (const theatre of THEATRES) {
    46:       insertTheatre.run(theatre.name, theatre.location, theatre.name);
    47:     }
    48:     const movieIds = db.prepare("SELECT id FROM movies").all() as { id: number }[];
    49:     const theatreIds = db.prepare("SELECT id FROM theatres").all() as { id: number }[];
    50:     for (const movie of movieIds) {
    51:       for (const theatre of theatreIds) {
    52:         insertMapping.run(movie.id, theatre.id);
    53:       }
    54:     }
    55:   });
    56: 
    57:   seedAll();
    58: }","total_lines":58,"sha256":"30ad759d55880e155554a35ba19b357f1f4bf50e2f10067c01189dba94e2d9dc","lines_returned":58,"truncated":false,"next_offset":null,"summary":"Read backend/src/db/seed.ts — 58 lines"},"error":null,"decided_action":null,"persona_delta":null}

