     4: /** The hardcoded OTP accepted by this replica (no real SMS provider). */
     5: export const HARDCODED_OTP = "1234";
     6: 
     7: /**
     8:  * Authentication service.
     9:  *
    10:  * Implements the mobile-number + hardcoded-OTP login flow. No user record is
    11:  * persisted; a successful OTP verification issues a signed session token.
    12:  */
    13: export class AuthService {
    14:   /**
    15:    * Begin a login by validating the mobile number.
    16:    *
    17:    * Args:
    18:    *   mobile: The user's mobile number.
    19:    *
    20:    * Returns:
    21:    *   True when the mobile number is a valid 10-digit identifier.
    22:    */
    23:   initiateLogin(mobile: string): boolean {
    24:     return /^[0-9]{10}$/.test(mobile);
    25:   }
    26: 
    27:   /**
    28:    * Verify the OTP and, on success, issue a session token.
    29:    *
    30:    * Args:
    31:    *   mobile: The user's mobile number.
    32:    *   otp: The one-time password entered by the user.
    33:    *
    34:    * Returns:
    35:    *   A signed JWT session token when the OTP matches.
    36:    *
    37:    * Raises:
    38:    *   Error: With `status: 401` when the OTP does not match.
    39:    */
    40:   verifyOtp(mobile: string, otp: string): string {
    41:     if (!this.initiateLogin(mobile)) {
    42:       const err = new Error("Invalid mobile number") as Error & {
    43:         status?: number;
    44:       };
    45:       err.status = 400;
    46:       throw err;
    47:     }
    48:     if (otp !== HARDCODED_OTP) {
    49:       const err = new Error("Invalid OTP") as Error & { status?: number };
    50:       err.status = 401;
    51:       throw err;
    52:     }
    53:     return jwt.sign({ mobile }, config.jwtSecret, { expiresIn: "2h" });
    54:   }
    55: }
    56: 
    57: export const authService = new AuthService();","total_lines":57,"sha256":"87367dd33751e12c5dbbd54c72dcb161267fa2f62abe4e0ff3a8f8964a549263","lines_returned":57,"truncated":false,"next_offset":null,"summary":"Read backend/src/services/auth.service.ts — 57 lines"},"error":null,"decided_action":null,"persona_delta":null}

