    30: export class BookingsService {
    31:   /**
    32:    * Create and persist a booking.
    33:    *
    34:    * Args:
    35:    *   input: The booking details.
    36:    *
    37:    * Returns:
    38:    *   The booking confirmation with a generated confirmation id.
    39:    *
    40:    * Raises:
    41:    *   Error: With `status: 404` when the movie or theatre does not exist.
    42:    */
    43:   createBooking(input: CreateBookingInput): BookingConfirmation {
    44:     const movie = moviesService.getMovie(input.movieId);
    45:     if (!movie) {
    46:       const err = new Error("Movie not found") as Error & { status?: number };
    47:       err.status = 404;
    48:       throw err;
    49:     }
    50:     const theatre = theatresService.getTheatre(input.theatreId);
    51:     if (!theatre) {
    52:       const err = new Error("Theatre not found") as Error & { status?: number };
    53:       err.status = 404;
    54:       throw err;
    55:     }
    56: 
    57:     const confirmationId = `BMS-${randomBytes(4).toString("hex").toUpperCase()}`;
    58:     const db = getDb();
    59:     const result = db
    60:       .prepare(
    61:         `INSERT INTO bookings
    62:          (confirmation_id, mobile, movie_id, theatre_id, seats, total_price, payment_method)
    63:          VALUES (?, ?, ?, ?, ?, ?, ?)`
    64:       )
    65:       .run(
    66:         confirmationId,
    67:         input.mobile,
    68:         input.movieId,
    69:         input.theatreId,
    70:         JSON.stringify(input.seats),
    71:         input.totalPrice,
    72:         input.paymentMethod
    73:       );
    74: 
    75:     return {
    76:       id: Number(result.lastInsertRowid),
    77:       confirmationId,
    78:       movie: movie.title,
    79:       theatre: theatre.name,
    80:       seats: input.seats,
    81:       totalPrice: input.totalPrice,
    82:     };
    83:   }
    84: 
    85:   /**
    86:    * Fetch a persisted booking by id.
