    18:   return (req: Request, res: Response, next: NextFunction): void => {
    19:     try {
    20:       req.body = schema.parse(req.body);
    21:       next();
    22:     } catch (err) {
    23:       if (err instanceof ZodError) {
    24:         const message = err.errors
    25:           .map((e) => `${e.path.join(".")}: ${e.message}`)
