    27: /** A confirmed booking returned by the backend. */
    28: export interface BookingConfirmation {
    29:   id: number;
    30:   confirmationId: string;
    31:   movie: string;
    32:   theatre: string;
    33:   seats: string[];
    34:   totalPrice: number;
    35: }
    36: 
    37: /** Payload submitted to create a booking. */
    38: export interface BookingPayload {
    39:   mobile: string;
    40:   movieId: number;
    41:   theatreId: number;
    42:   seats: string[];
    43:   totalPrice: number;
    44:   paymentMethod: "card" | "upi";
    45: }
    46: 
    47: /** Error thrown for non-2xx API responses, carrying the server message. */
    48: export class ApiError extends Error {
    49:   constructor(message: string, public readonly status: number) {
    50:     super(message);
    51:     this.name = "ApiError";
    52:   }
    53: }
    54: 
    55: /**
    56:  * Perform a JSON request against the backend and unwrap the envelope.
    57:  *
    58:  * Args:
    59:  *   path: The request path beginning with `/api`.
    60:  *   options: Fetch init options (method, body, headers).
    61:  *
    62:  * Returns:
    63:  *   The parsed JSON response body.
    64:  *
    65:  * Raises:
    66:  *   ApiError: When the response is not OK, carrying the server's error message.
    67:  */
    68: async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
    69:   const res = await fetch(`${BASE_URL}${path}`, {
    70:     headers: { "Content-Type": "application/json", ...options.headers },
    71:     ...options,
    72:   });
    73:   const body = (await res.json().catch(() => ({}))) as {
    74:     success?: boolean;
    75:     error?: string;
    76:   } & T;
    77:   if (!res.ok) {
    78:     throw new ApiError(body.error ?? `Request failed (${res.status})`, res.status);
    79:   }
    80:   return body;
    81: }
    82: 
    83: /** Begin login by submitting a mobile number. */
    84: export function login(mobile: string) {
    85:   return request<{ success: true; message: string }>("/api/auth/login", {
    86:     method: "POST",
    87:     body: JSON.stringify({ mobile }),
    88:   });
    89: }
