    92: export function verifyOtp(mobile: string, otp: string) {
    93:   return request<{ success: true; token: string }>("/api/auth/verify", {
    94:     method: "POST",
    95:     body: JSON.stringify({ mobile, otp }),
    96:   });
    97: }
